package ch.conciliations.mabecoju.domain.booking;

import java.util.Arrays;

/** Column {@code pay_kind} of {@code book_payments}. */
public enum PaymentKind {
    UNDEFINED(0),
    BANK(1),
    EXPENSE(2),
    /** Generated by the execution of a standing order. */
    PERMANENT(3);

    private final int code;

    PaymentKind(int code) {
        this.code = code;
    }

    public int code() {
        return code;
    }

    public static PaymentKind fromCode(Integer code) {
        if (code == null) {
            return UNDEFINED;
        }
        return Arrays.stream(values()).filter(k -> k.code == code).findFirst().orElse(UNDEFINED);
    }
}
